program = '''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    foreground = [v for v, n in counts.most_common() if v != bg][:2]
    if len(foreground) < 2:
        return [row[:] for row in grid]
    known = {bg, *foreground}
    best = {}
    # Rectangular objects remain recognizable despite a few overwritten cells.
    for color in foreground:
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        area = (r1-r0+1) * (c1-c0+1)
                        n = sum(grid[r][c] == color for r in range(r0,r1+1) for c in range(c0,c1+1))
                        if n < 4 or n / area < 0.75:
                            continue
                        edge_rows = [sum(grid[r][c] == color for c in range(c0,c1+1)) / (c1-c0+1) for r in (r0,r1)]
                        edge_cols = [sum(grid[r][c] == color for r in range(r0,r1+1)) / (r1-r0+1) for c in (c0,c1)]
                        if min(edge_rows + edge_cols) < 0.5:
                            continue
                        score = n / area
                        for r in range(r0,r1+1):
                            for c in range(c0,c1+1):
                                if grid[r][c] not in known:
                                    key = (r,c)
                                    old = best.get(key)
                                    if old is None or score > old[0]:
                                        best[key] = (score, color)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in known:
                out[r][c] = best.get((r,c), (0,bg))[1]
    return out
'''
